def solve(height):
    if not height:
        return 0

    max_height = max(height)
    left = 0
    right = len(height) - 1
    total_water = 0

    while left < right:
        if height[left] < height[right]:
            # Find the next bar that is taller than current left
            next_left = left + 1
            while next_left <= right and height[next_left] <= height[left]:
                next_left += 1
            if next_left == right:
                # No higher bar found, move right
                right -= 1
            else:
                # Calculate water trapped between left and next_left
                for i in range(left + 1, next_left):
                    total_water += height[left] - height[i]
                left = next_left
        else:
            # Find the next bar that is taller than current right
            next_right = right - 1
            while next_right >= left and height[next_right] <= height[right]:
                next_right -= 1
            if next_right == left:
                # No higher bar found, move left
                left += 1
            else:
                # Calculate water trapped between right and next_right
                for i in range(next_right + 1, right):
                    total_water += height[right] - height[i]
                right = next_right

    return total_water

