        return 0

    from collections import deque

    n = len(height)
    visited = [False] * n
    queue = deque()

    # Start with all the lowest points (zero height bars)
    for i in range(n):
        if height[i] == 0:
            queue.append(i)
            visited[i] = True

    total_water = 0
    while queue:
        i = queue.popleft()
        for neighbor in [i - 1, i + 1]:
            if 0 <= neighbor < n and not visited[neighbor]:
                visited[neighbor] = True
                if height[neighbor] == 0:
                    total_water += 1
                    queue.append(neighbor)
                else:
                    queue.append(neighbor)

    return total_water

