        return trap_water(start, max_index) + trap_water(max_index, end) + \
               max(0, min(height[start], height[end]) - height[max_index]) * (max_index - start) + \
               max(0, min(height[max_index], height[end]) - height[max_index]) * (end - max_index)

    return trap_water(0, len(height)-1)

