def solve(height):
    if not height:
        return 0

    from collections import deque

    n = len(height)
    visited = [False] * n
    queue = deque()

    # Start from the lowest bar
    min_height = min(height)
    for i in range(n):
        if height[i] == min_height:
            queue.append(i)
            visited[i] = True

    total_water = 0

    while queue:
        i = queue.popleft()
        for neighbor in [i - 1, i + 1]:
            if 0 <= neighbor < n and not visited[neighbor]:
                if height[neighbor] < height[i]:
                    total_water += height[i] - height[neighbor]
                visited[neighbor] = True
                queue.append(neighbor)

    return total_water

